// --- Rotation matrix for pi/3 (60 degrees)
#define rot(a) mat2(cos(1.047*(a) + vec4(0,1.57,-1.57,0)))

// --- Curved line segment distance function (constrained arcs)
float curvedLineDistance(vec2 U, vec2 P, vec2 _P, float density) {
    // Treat the line segment as a constrained circular arc
    vec2 mid = (P + _P) / 2.0; // Midpoint of the line segment
    vec2 dir = normalize(_P - P); // Direction of the line segment
    float curvature = 1.5; // Curvature factor (adjust for more/less curvature)
    vec2 center = mid + vec2(-dir.y, dir.x) * curvature * length(_P - P); // Center of the arc

    // Calculate distance from U to the constrained circular arc
    float radius = length(_P - P) * curvature;
    vec2 toU = U - center;
    float angle = atan(toU.y, toU.x); // Angle of U relative to the arc center
    vec2 arcPoint = center + radius * vec2(cos(angle), sin(angle)); // Closest point on the arc

    // Ensure the arcPoint lies between P and _P
    float t = dot(arcPoint - P, _P - P) / dot(_P - P, _P - P);
    t = clamp(t, 0.0, 1.0); // Constrain t to [0, 1]
    arcPoint = mix(P, _P, t); // Project arcPoint onto the line segment

    return length(U - arcPoint); // Distance to the constrained arc
}

// --- L-system parameters
float p[] = float[](.318, -1., -2., 1., 2., 0., 1.); // Turn angles (multiples of pi/3)
int s[] = int[](1, -1, -1, 1, 1, 1, -1); // Draw direction: forward (1) or reverse (-1)

// --- Macro to define recursive drawing functions
#define Rec(draw, draw2)                                      \
float draw(vec2 U, vec2 P, vec2 _P, float density) {          \
    vec2 D = _P - P;                                          \
    if (length(U - (P + _P) / 2.) > .88 * length(D)) return 9.; \
    float d = 9.;                                             \
    for (int i = 0; i < p.length(); i++) {                    \
        _P = P;                                               \
        D *= rot(p[i]);                                       \
        P += .378 * D;                                        \
        if (density > 0.0) {                                  \
            d = min(d, s[i] > 0 ? draw2(U, _P, P, density - 1.0) : draw2(U, P, _P, density - 1.0)); \
        } else {                                              \
            float dist = s[i] > 0 ? curvedLineDistance(U, _P, P, density) : curvedLineDistance(U, P, _P, density); \
            d = min(d, dist); \
        }                                                     \
    }                                                         \
    return d;                                                 \
}

// --- Define the recursion levels (increased by two)
Rec(draw6, curvedLineDistance)  
Rec(draw5, draw6)  
Rec(draw4, draw5)
Rec(draw3, draw4)
Rec(draw2, draw3)
Rec(draw1, draw2)

// --- 4x4 Bayer matrix for dithering
float bayer4x4(vec2 uv) {
    // Define the 4x4 Bayer matrix
    mat4 bayer = mat4(
        0.0,  8.0,  2.0, 10.0,
        12.0,  4.0, 14.0,  6.0,
        3.0, 11.0,  1.0,  9.0,
        15.0,  7.0, 13.0,  5.0
    );

    // Normalize the Bayer matrix to [0, 1]
    bayer /= 16.0;

    // Calculate the Bayer matrix index
    ivec2 coord = ivec2(mod(uv, 32.0));
    return bayer[coord.y][coord.x];
}

// --- Main function
void mainImage(out vec4 O, vec2 u) {
    vec2 R = iResolution.xy; // Screen resolution
    vec2 U = (2. * u - R) / min(R.x, R.y); // Normalized pixel coordinates (scaled to fit screen)

    // Shift the curve left and up
    float curveRadius = 1.0; // Approximate radius of the curve
    U += vec2(+0.75 * curveRadius, -0.5 * curveRadius); // Shift left and up

    vec2 P = vec2(1.0); // Starting point of the curve (scaled to fit screen)

    // Sample the input texture (iChannel0) for density control and color
    vec3 textureColor = texture(iChannel0, u / R).rgb; // RGB values from the texture

    // Use iMouse.x to scale the grayscale value for density control
    float grayscaleFactor = iMouse.x / R.x; // Normalize mouse x to [0, 1]
    float maskValue = textureColor.r * grayscaleFactor; // Scale grayscale value

    // Use iMouse.y to modulate the RGB values
    float rgbModFactor = iMouse.y / R.y; // Normalize mouse y to [0, 1]
    vec3 modifiedColor = mod(textureColor, rgbModFactor); // Modulate RGB values

    // Apply 4x4 Bayer dithering to the grayscale value
    float bayerThreshold = bayer4x4(u);
    float ditheredMaskValue = step(bayerThreshold, maskValue); // Apply Bayer threshold

    // Mix the original and modified colors based on the dithered grayscale value
    vec3 finalColor = mix(textureColor, modifiedColor, ditheredMaskValue - 0.3);

    // Map mask value to recursion depth (e.g., depth range 0 to 6)
    float depth = mix(0.0, 6.0, maskValue); // Increased depth range for more variation

    // Draw the Gosper curve with variable recursion depth
    float curveDistance = draw1(U, -P, P, depth);

    // Output the result with smoothstep for anti-aliasing and color
    float curveIntensity = smoothstep(3. / min(R.x, R.y), 0., curveDistance); // Use curveDistance directly
    O = vec4(finalColor * curveIntensity, 1.0); // Apply modulated color to the curve
}
